using System.Collections.Generic; using UnityEngine; namespace Reflectable { [CreateAssetMenu(menuName="Reflectable/Character Database")] public sealed class CharacterDatabase:ScriptableObject { public List<CharacterData> characters=new List<CharacterData>(); public CharacterData Find(string id){return characters.Find(x=>x&&x.characterId==id);} public CharacterData Default=>characters.Count>0?characters[0]:null; } }
